void CLX::Mul(const CLX &ref)
{
	double R, J;
	R = r * ref.r - j * ref.j;
	J = r * ref.j + j * ref.r;
	r = R;
	j = J;
}

void CLX::Div(const CLX &ref)
{
	double R, J, D;
	R = r * ref.r + j * ref.j;
	J = j * ref.r - r * ref.j;
	D = ref.r * ref.r + ref.j * ref.j;
	r = R/D;
	j = J/D;
}

